package com.riyadsalihin.amharic.data

import android.content.res.AssetManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import com.riyadsalihin.amharic.util.ArabicText

/**
 * Reads the bundled, offline content. Everything is loaded lazily from the
 * asset files generated by tools/build_content.py.
 */
class ContentRepository(private val assets: AssetManager) {

    private val json = Json { ignoreUnknownKeys = true }
    private val mutex = Mutex()
    private var indexCache: ContentIndex? = null
    private val bookCache = mutableMapOf<Int, BookContent>()
    private var searchCache: List<SearchResult>? = null

    suspend fun index(): ContentIndex = mutex.withLock {
        indexCache ?: readIndex().also { indexCache = it }
    }

    suspend fun book(bookId: Int): BookContent = mutex.withLock {
        bookCache[bookId] ?: readBook(bookId).also { bookCache[bookId] = it }
    }

    /**
     * Full-text search over Arabic, Amharic and English. Results are ordered by
     * hadith number so a search reads like the book itself.
     */
    suspend fun search(query: String, limit: Int = 120): List<SearchResult> {
        val needle = query.trim()
        if (needle.length < 2) return emptyList()
        val all = allHadiths()
        val arabicNeedle = ArabicText.normalize(needle)
        val plainNeedle = needle.lowercase()
        return withContext(Dispatchers.Default) {
            all.asSequence()
                .filter { result ->
                    val amharic = result.hadith.amharic
                    ArabicText.normalize(result.hadith.arabic).contains(arabicNeedle) ||
                        result.hadith.english.lowercase().contains(plainNeedle) ||
                        (amharic != null && amharic.lowercase().contains(plainNeedle))
                }
                .take(limit)
                .toList()
        }
    }

    suspend fun hadiths(numbers: Set<Int>): List<SearchResult> {
        if (numbers.isEmpty()) return emptyList()
        return allHadiths().filter { it.hadith.number in numbers }
    }

    private suspend fun allHadiths(): List<SearchResult> = mutex.withLock {
        searchCache ?: run {
            val loadedIndex = indexCache ?: readIndex().also { indexCache = it }
            val results = mutableListOf<SearchResult>()
            for (summary in loadedIndex.books) {
                val content = bookCache[summary.id] ?: readBook(summary.id).also { bookCache[summary.id] = it }
                for (hadith in content.hadiths) {
                    results.add(SearchResult(summary.id, summary.titleAm, summary.titleEn, hadith))
                }
            }
            results.sortedBy { it.hadith.number }.also { searchCache = it }
        }
    }

    private suspend fun readIndex(): ContentIndex = withContext(Dispatchers.IO) {
        assets.open("content/index.json").bufferedReader().use { reader ->
            json.decodeFromString(ContentIndex.serializer(), reader.readText())
        }
    }

    private suspend fun readBook(bookId: Int): BookContent = withContext(Dispatchers.IO) {
        val path = "content/books/book-%02d.json".format(bookId)
        assets.open(path).bufferedReader().use { reader ->
            json.decodeFromString(BookContent.serializer(), reader.readText())
        }
    }
}
